/// The harness-owned register image, and the oracle for the ordering rules.
#[derive(Clone, Copy)]
struct ImageI2c1 {
    rcc: [u32; 76],
    pwr: [u32; 11],
    gpiob: [u32; 10],
    i2c1: [u32; 11],
    /// The running action, its `match` arm's number: whose footprint a
    /// write may change.
    running: u8,
}

impl ImageI2c1 {
    fn slot(&mut self, block: Block, offset: usize) -> &mut u32 {
        let words: &mut [u32] = match block {
            Block::Rcc => &mut self.rcc,
            Block::Pwr => &mut self.pwr,
            Block::GpioB => &mut self.gpiob,
            Block::I2c1 => &mut self.i2c1,
            _ => unreachable!("`clocked` refuses a block outside the part"),
        };
        kani::assert(
            offset % 4 == 0 && offset / 4 < words.len(),
            "register access past the end of its block",
        );
        &mut words[offset / 4]
    }

    /// A gated block may not be read or written.
    fn clocked(&self, block: Block) {
        match block {
            Block::Rcc => {}
            Block::Pwr => {}
            Block::GpioB => kani::assert(
                self.rcc[56] & 0x00000002 != 0,
                "GpioB accessed before RCC_AHB4ENR bit 1 is set",
            ),
            Block::I2c1 => kani::assert(
                self.rcc[58] & 0x00200000 != 0,
                "I2c1 accessed before RCC_APB1LENR bit 21 is set",
            ),
            _ => {
                kani::assert(false, "a block outside the i2c1 part was accessed");
                kani::assume(false);
            }
        }
    }

    /// The bits the running action may change in one register: the
    /// generator's footprint of that action, from the oracle's own facts.
    fn footprint(&self, block: Block, offset: usize) -> u32 {
        match (self.running, block, offset) {
            (0, Block::GpioB, 0x4) => 0xffffffff,
            (0, Block::GpioB, 0xc) => 0xffffffff,
            (0, Block::Rcc, 0xe0) => 0x00000002,
            (1, Block::Rcc, 0xe8) => 0x00200000,
            (2, Block::GpioB, 0x0) => 0x00003000,
            (2, Block::GpioB, 0x8) => 0x00003000,
            (2, Block::GpioB, 0x20) => 0x0f000000,
            (3, Block::GpioB, 0x0) => 0x0000c000,
            (3, Block::GpioB, 0x8) => 0x0000c000,
            (3, Block::GpioB, 0x20) => 0xf0000000,
            (4, Block::I2c1, 0x0) => 0xffffffff,
            (4, Block::I2c1, 0x10) => 0xffffffff,
            (4, Block::I2c1, 0x28) => 0xffffffff,
            _ => 0,
        }
    }

    /// The rely: every bit an action outside the i2c1 part may change
    /// is arbitrary. A stored `BSRR` is the last value written, which any
    /// writer of its port replaces whole, so it is arbitrary whole.
    fn rely(&mut self) {
        self.rcc[56] = (self.rcc[56] & !0x00000001) | (kani::any::<u32>() & 0x00000001);
        self.rcc[60] = (self.rcc[60] & !0x00001000) | (kani::any::<u32>() & 0x00001000);
    }
}

impl sealed::Sealed for ImageI2c1 {}

impl Registers for ImageI2c1 {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        self.clocked(block);
        kani::assert(
            !(block == Block::GpioB && offset == 0x04),
            "GpioB OTYPER was read",
        );
        kani::assert(
            !(block == Block::GpioB && offset == 0x0c),
            "GpioB PUPDR was read",
        );
        kani::assert(
            !(block == Block::I2c1 && offset == 0x10),
            "I2c1 TIMINGR was read",
        );
        *self.slot(block, offset)
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        self.clocked(block);
        // PWR (RM0433 Rev 9 §6.8): only `CR3` and `D3CR` are written, and
        // `D3CR.VOSRDY` is read-only, so a write leaves it as it was.
        let value = if block == Block::Pwr {
            kani::assert(
                offset == 0x00c || offset == 0x018,
                "a PWR register other than CR3 and D3CR was written",
            );
            if offset == 0x018 {
                (value & !0x00002000) | (self.pwr[6] & 0x00002000)
            } else {
                value
            }
        } else {
            value
        };
        if block == Block::I2c1 && offset == 0x10 {
            kani::assert(
                self.i2c1[0] & 0x00000001 == 0,
                "I2c1 TIMINGR written while the peripheral is enabled",
            );
        }
        if block == Block::I2c1 && offset == 0x10 {
            kani::assert(
                self.i2c1[0] == 0x00000000,
                "I2c1 TIMINGR written while CR1 is not the rule's word (aethelgard_ir::silicon::i2c_cr1)",
            );
        }
        if block == Block::GpioB && offset == 0x04 {
            kani::assert(value == 0x000000c0, "GpioB OTYPER is not the solved word, whole");
        }
        if block == Block::GpioB && offset == 0x0c {
            kani::assert(value == 0x00000100, "GpioB PUPDR is not the solved word, whole");
        }
        if block == Block::GpioB && offset == 0x18 {
            kani::assert(false, "GpioB BSRR write touches a pin no solved output of the i2c1 part owns");
            // The level it leaves: a set bit wins over a reset bit (RM0433 §11.4.7).
            let level = (self.gpiob[5] & !(value >> 16)) | (value & 0xffff);
            kani::assert(
                (level ^ self.gpiob[5]) & !self.footprint(block, 0x14) == 0,
                "GpioB ODR: a level changed outside the running action's footprint",
            );
            self.gpiob[5] = level;
        }
        if block == Block::GpioB && offset == 0x00 {
            let old = self.gpiob[0];
            if value & 0x00003000 != old & 0x00003000 {
                kani::assert(value & 0x00003000 == 0x00002000, "PB6's mode moved to one its role never takes");
                kani::assert(
                    self.gpiob[1] & 0x00000040 == 0x00000040
                        && self.gpiob[2] & 0x00003000 == 0x00000000
                        && self.gpiob[3] & 0x00003000 == 0x00000000
                        && self.gpiob[8] & 0x0f000000 == 0x04000000,
                    "PB6 entered its mode before its other fields were final",
                );
            }
            if value & 0x0000c000 != old & 0x0000c000 {
                kani::assert(value & 0x0000c000 == 0x00008000, "PB7's mode moved to one its role never takes");
                kani::assert(
                    self.gpiob[1] & 0x00000080 == 0x00000080
                        && self.gpiob[2] & 0x0000c000 == 0x00000000
                        && self.gpiob[3] & 0x0000c000 == 0x00000000
                        && self.gpiob[8] & 0xf0000000 == 0x40000000,
                    "PB7 entered its mode before its other fields were final",
                );
            }
            kani::assert(
                value & !0x0000f000 == old & !0x0000f000,
                "a GpioB MODER write moved a pin the topology does not use",
            );
        }
        if block != Block::Pwr {
            let changed = if matches!((block, offset), (Block::GpioB, 0x18)) {
                value
            } else {
                *self.slot(block, offset) ^ value
            };
            kani::assert(
                changed & !self.footprint(block, offset) == 0,
                "a write changed a bit outside the running action's footprint",
            );
        }
        *self.slot(block, offset) = value;
    }
    // A byte access models the register as its word: the low byte read, the
    // byte written zero-extended, under every rule above.
    fn read8(&mut self, token: sealed::Token, block: Block, offset: usize) -> u8 {
        self.read(token, block, offset).to_le_bytes()[0]
    }
    fn write8(&mut self, token: sealed::Token, block: Block, offset: usize, value: u8) {
        self.write(token, block, offset, u32::from(value));
    }
}

/// The i2c1 part's share of the state the specification allows, from
/// any starting image: its own fields as solved, and every bit no action
/// may change unchanged. Another part's bits are that part's to prove.
fn check_final_i2c1(before: &ImageI2c1, after: &ImageI2c1, i2c1_timingr: u32) {
    // PWR is before plus exactly the declared supply and VOS Scale 2
    // (aethelgard_ir::vos::cr3_supply_bits, D3CR_VOS_SCALE2).
    kani::assert(
        after.pwr[3] == (before.pwr[3] & !0x00000007) | 0x00000002,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: CR3's supply bits are not the rule's, or another bit moved",
    );
    kani::assert(
        after.pwr[6] & 0x0000c000 == 0x00008000,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: D3CR.VOS is not 10",
    );
    kani::assert(
        after.pwr[6] & !0x00002000 == 0x00008000,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: D3CR is not the rule's whole word",
    );
    kani::assert(after.pwr[0] == before.pwr[0], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 0 changed");
    kani::assert(after.pwr[1] == before.pwr[1], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 1 changed");
    kani::assert(after.pwr[2] == before.pwr[2], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 2 changed");
    kani::assert(after.pwr[4] == before.pwr[4], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 4 changed");
    kani::assert(after.pwr[5] == before.pwr[5], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 5 changed");
    kani::assert(after.pwr[7] == before.pwr[7], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 7 changed");
    kani::assert(after.pwr[8] == before.pwr[8], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 8 changed");
    kani::assert(after.pwr[9] == before.pwr[9], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 9 changed");
    kani::assert(after.pwr[10] == before.pwr[10], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 10 changed");
    kani::assert(after.gpiob[1] == 0x000000c0, "GpioB OTYPER is not the solved word");
    kani::assert(after.gpiob[3] == 0x00000100, "GpioB PUPDR is not the solved word");
    kani::assert(
        after.gpiob[0] & 0x0000f000 == 0x0000a000,
        "GpioB word 0: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[0] & !0x0000f000 == before.gpiob[0] & !0x0000f000,
        "GpioB word 0: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[2] & 0x0000f000 == 0x00000000,
        "GpioB word 2: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[2] & !0x0000f000 == before.gpiob[2] & !0x0000f000,
        "GpioB word 2: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[8] & 0xff000000 == 0x44000000,
        "GpioB word 8: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[8] & !0xff000000 == before.gpiob[8] & !0xff000000,
        "GpioB word 8: an unsolved pin's field changed",
    );
    kani::assert(after.gpiob[4] == before.gpiob[4], "GpioB word 4 changed");
    kani::assert(after.gpiob[5] == before.gpiob[5], "GpioB word 5 changed");
    kani::assert(after.gpiob[6] == before.gpiob[6], "GpioB word 6 changed");
    kani::assert(after.gpiob[7] == before.gpiob[7], "GpioB word 7 changed");
    kani::assert(after.gpiob[9] == before.gpiob[9], "GpioB word 9 changed");
    let mut rcc = before.rcc;
    rcc[56] |= 0x00000002;
    rcc[58] |= 0x00200000;
    let mut rely = [0u32; 76];
    rely[56] = 0x00000001;
    rely[60] = 0x00001000;
    // Word by word: `==` on the arrays is a `memcmp` loop under CBMC.
    for i in 0..76 {
        kani::assert(
            after.rcc[i] & !rely[i] == rcc[i] & !rely[i],
            "RCC is not before plus exactly the solved clock gates and selections",
        );
    }
    kani::assert(
        after.i2c1[0] == 0x00000001,
        "I2c1 CR1 is not the rule's word with PE (aethelgard_ir::silicon::i2c_cr1)",
    );
    kani::assert(
        after.i2c1[4] == i2c1_timingr,
        "I2c1 TIMINGR is not the chosen speed's",
    );
    kani::assert(after.i2c1[1] == before.i2c1[1], "I2c1 word 1 changed");
    kani::assert(after.i2c1[2] == before.i2c1[2], "I2c1 word 2 changed");
    kani::assert(after.i2c1[3] == before.i2c1[3], "I2c1 word 3 changed");
    kani::assert(after.i2c1[5] == before.i2c1[5], "I2c1 word 5 changed");
    kani::assert(after.i2c1[6] == before.i2c1[6], "I2c1 word 6 changed");
    kani::assert(after.i2c1[7] == before.i2c1[7], "I2c1 word 7 changed");
    kani::assert(after.i2c1[8] == before.i2c1[8], "I2c1 word 8 changed");
    kani::assert(after.i2c1[9] == before.i2c1[9], "I2c1 word 9 changed");
}

/// The i2c1 part of the whole schedule (`AET-WO-3303` §1.2): every order
/// the typestate API admits of its 6 actions, under the rely that
/// any other part's action may have run between any two of them. Each
/// write may change only its running action's footprint; the parts'
/// footprints are disjoint, so together the parts prove every schedule
/// of the whole board.
/// No step touches a USART, its pins or its clock gate: the final check holds
/// them at their starting values, the image holds no USART block, and any
/// access to one fails. Each port's bring-up is
/// `usartN_start_writes_the_solved_values`' (`AET-WO-4300b`: USART steps in
/// this schedule ran out of CBMC's memory).
#[kani::proof]
#[kani::unwind(77)]
fn every_valid_sequence_i2c1() {
    let mut img = ImageI2c1 {
        rcc: kani::any(),
        pwr: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        running: u8::MAX,
    };
    let before = img;
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    // The bring-up's first step, as `main` takes it (`AET-WO-4240v` §1.4): it
    // touches only PWR (`pwr_scale2_is_once_in_order_and_bounded`), and no
    // action touches PWR, so it commutes with every action.
    let scale2 = board.pwr.scale2(&mut img, 1);
    kani::assume(scale2.is_ok());
    let scale2 = scale2.unwrap();
    let mut gpiob = Some(board.gpiob);
    let mut i2c1 = Some(board.i2c1);
    let mut i2c1_clocked = None;
    let mut i2c1_done = false;
    let mut i2c1_timingr = 0u32;
    let mut pb6 = None;
    let mut pb6_done = None;
    let mut pb7 = None;
    let mut pb7_done = None;
    let mut clock = None;
    for _ in 0..6 {
        img.rely();
        let action: u8 = kani::any();
        match action {
            0 => {
                kani::assume(gpiob.is_some());
                img.running = 0;
                let pins = rcc.enable_gpiob(&mut img, gpiob.take().unwrap(), scale2).split(&mut img);
                pb6 = Some(pins.pb6);
                pb7 = Some(pins.pb7);
            }
            1 => {
                kani::assume(i2c1.is_some());
                img.running = 1;
                i2c1_clocked = Some(rcc.enable_i2c1(&mut img, i2c1.take().unwrap(), scale2));
            }
            2 => {
                kani::assume(pb6.is_some());
                img.running = 2;
                let pin = pb6.take().unwrap().into_i2c1_scl(&mut img);
                pb6_done = Some(pin);
            }
            3 => {
                kani::assume(pb7.is_some());
                img.running = 3;
                let pin = pb7.take().unwrap().into_i2c1_sda(&mut img);
                pb7_done = Some(pin);
            }
            4 => {
                kani::assume(i2c1_clocked.is_some() && clock.is_some() && pb6_done.is_some() && pb7_done.is_some());
                img.running = 4;
                let i = i2c1_clocked.take().unwrap();
                let speed: u8 = kani::any();
                if speed == 0 {
                    i2c1_timingr = 0x50d32a40;
                    let mut bus = i.init::<i2c1_speed::Standard100k, _>(&mut img, clock.as_ref().unwrap(), pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Standard100k");
                    if kani::any() {
                        let levels = [img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                } else {
                    i2c1_timingr = 0x10c7123c;
                    let mut bus = i.init::<i2c1_speed::Fast400k, _>(&mut img, clock.as_ref().unwrap(), pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Fast400k");
                    if kani::any() {
                        let levels = [img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                }
                i2c1_done = true;
            }
            5 => {
                kani::assume(clock.is_none());
                img.running = 5;
                let read = rcc.reset_clock(&mut img, &scale2);
                kani::assume(read.is_ok());
                clock = read.ok();
                kani::cover!(true, "the reset clock was read");
            }
            _ => kani::assume(false),
        }
    }
    kani::assert(i2c1_done, "the schedule did not start I2C1");
    check_final_i2c1(&before, &img, i2c1_timingr);
    kani::cover!(true, "the end of a complete schedule is reachable");
}

/// The harness-owned register image, and the oracle for the ordering rules.
#[derive(Clone, Copy)]
struct ImageSpi1 {
    rcc: [u32; 76],
    pwr: [u32; 11],
    gpioa: [u32; 10],
    spi1: [u32; 21],
    /// The running action, its `match` arm's number: whose footprint a
    /// write may change.
    running: u8,
}

impl ImageSpi1 {
    fn slot(&mut self, block: Block, offset: usize) -> &mut u32 {
        let words: &mut [u32] = match block {
            Block::Rcc => &mut self.rcc,
            Block::Pwr => &mut self.pwr,
            Block::GpioA => &mut self.gpioa,
            Block::Spi1 => &mut self.spi1,
            _ => unreachable!("`clocked` refuses a block outside the part"),
        };
        kani::assert(
            offset % 4 == 0 && offset / 4 < words.len(),
            "register access past the end of its block",
        );
        &mut words[offset / 4]
    }

    /// A gated block may not be read or written.
    fn clocked(&self, block: Block) {
        match block {
            Block::Rcc => {}
            Block::Pwr => {}
            Block::GpioA => kani::assert(
                self.rcc[56] & 0x00000001 != 0,
                "GpioA accessed before RCC_AHB4ENR bit 0 is set",
            ),
            Block::Spi1 => kani::assert(
                self.rcc[60] & 0x00001000 != 0,
                "Spi1 accessed before RCC_APB2ENR bit 12 is set",
            ),
            _ => {
                kani::assert(false, "a block outside the spi1 part was accessed");
                kani::assume(false);
            }
        }
    }

    /// The bits the running action may change in one register: the
    /// generator's footprint of that action, from the oracle's own facts.
    fn footprint(&self, block: Block, offset: usize) -> u32 {
        match (self.running, block, offset) {
            (0, Block::GpioA, 0x4) => 0xffffffff,
            (0, Block::GpioA, 0xc) => 0xffffffff,
            (0, Block::Rcc, 0xe0) => 0x00000001,
            (1, Block::Rcc, 0xf0) => 0x00001000,
            (2, Block::GpioA, 0x0) => 0x00000003,
            (2, Block::GpioA, 0x8) => 0x00000003,
            (2, Block::GpioA, 0x14) => 0x00000001,
            (2, Block::GpioA, 0x18) => 0x00010001,
            (3, Block::GpioA, 0x0) => 0x00000c00,
            (3, Block::GpioA, 0x8) => 0x00000c00,
            (3, Block::GpioA, 0x20) => 0x00f00000,
            (4, Block::GpioA, 0x0) => 0x00003000,
            (4, Block::GpioA, 0x8) => 0x00003000,
            (4, Block::GpioA, 0x20) => 0x0f000000,
            (5, Block::GpioA, 0x0) => 0x0000c000,
            (5, Block::GpioA, 0x8) => 0x0000c000,
            (5, Block::GpioA, 0x20) => 0xf0000000,
            (6, Block::GpioA, 0x14) => 0x00000001,
            (6, Block::GpioA, 0x18) => 0x00010001,
            (6, Block::Spi1, 0x0) => 0xffffffff,
            (6, Block::Spi1, 0x8) => 0xffffffff,
            (6, Block::Spi1, 0xc) => 0xffffffff,
            _ => 0,
        }
    }

    /// The rely: every bit an action outside the spi1 part may change
    /// is arbitrary. A stored `BSRR` is the last value written, which any
    /// writer of its port replaces whole, so it is arbitrary whole.
    fn rely(&mut self) {
        self.rcc[56] = (self.rcc[56] & !0x00000002) | (kani::any::<u32>() & 0x00000002);
        self.rcc[58] = (self.rcc[58] & !0x00200000) | (kani::any::<u32>() & 0x00200000);
    }
}

impl sealed::Sealed for ImageSpi1 {}

impl Registers for ImageSpi1 {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        self.clocked(block);
        kani::assert(
            !(block == Block::GpioA && offset == 0x04),
            "GpioA OTYPER was read",
        );
        kani::assert(
            !(block == Block::GpioA && offset == 0x0c),
            "GpioA PUPDR was read",
        );
        kani::assert(
            !(block == Block::Spi1 && offset == 0x08),
            "Spi1 CFG1 was read",
        );
        kani::assert(
            !(block == Block::Spi1 && offset == 0x0c),
            "Spi1 CFG2 was read",
        );
        *self.slot(block, offset)
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        self.clocked(block);
        // PWR (RM0433 Rev 9 §6.8): only `CR3` and `D3CR` are written, and
        // `D3CR.VOSRDY` is read-only, so a write leaves it as it was.
        let value = if block == Block::Pwr {
            kani::assert(
                offset == 0x00c || offset == 0x018,
                "a PWR register other than CR3 and D3CR was written",
            );
            if offset == 0x018 {
                (value & !0x00002000) | (self.pwr[6] & 0x00002000)
            } else {
                value
            }
        } else {
            value
        };
        if block == Block::Spi1 && offset == 0x0c {
            kani::assert(
                self.spi1[0] & 0x00000001 == 0,
                "Spi1 CFG2 written while the peripheral is enabled",
            );
        }
        if block == Block::Spi1 && offset == 0x08 {
            kani::assert(
                self.spi1[0] & 0x00000001 == 0,
                "Spi1 CFG1 written while the peripheral is enabled",
            );
        }
        if block == Block::Spi1 && offset == 0x00 && value & 0x00000001 != 0 {
            kani::assert(
                self.spi1[3] & 0x84400000 == 0x84400000,
                "Spi1 SPE set before CFG2 holds MASTER and SSM",
            );
            kani::assert(value & 0x00001000 != 0, "Spi1 SPE set without SSI");
        }
        if block == Block::GpioA && offset == 0x04 {
            kani::assert(value == 0x00000000, "GpioA OTYPER is not the solved word, whole");
        }
        if block == Block::GpioA && offset == 0x0c {
            kani::assert(value == 0x64000000, "GpioA PUPDR is not the solved word, whole");
        }
        if block == Block::GpioA && offset == 0x18 {
            kani::assert(value == 0x00000001 || value == 0x00010000, "GpioA BSRR write touches a pin no solved output of the spi1 part owns");
            // The level it leaves: a set bit wins over a reset bit (RM0433 §11.4.7).
            let level = (self.gpioa[5] & !(value >> 16)) | (value & 0xffff);
            kani::assert(
                (level ^ self.gpioa[5]) & !self.footprint(block, 0x14) == 0,
                "GpioA ODR: a level changed outside the running action's footprint",
            );
            self.gpioa[5] = level;
        }
        if block == Block::GpioA && offset == 0x00 {
            let old = self.gpioa[0];
            if value & 0x00000003 != old & 0x00000003 {
                kani::assert(value & 0x00000003 == 0x00000001, "PA0's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000001 == 0x00000000
                        && self.gpioa[2] & 0x00000003 == 0x00000000
                        && self.gpioa[3] & 0x00000003 == 0x00000000
                        && self.gpioa[6] == 0x00000001,
                    "PA0 entered its mode before its other fields were final",
                );
            }
            if value & 0x00000c00 != old & 0x00000c00 {
                kani::assert(value & 0x00000c00 == 0x00000800, "PA5's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000020 == 0x00000000
                        && self.gpioa[2] & 0x00000c00 == 0x00000400
                        && self.gpioa[3] & 0x00000c00 == 0x00000000
                        && self.gpioa[8] & 0x00f00000 == 0x00500000,
                    "PA5 entered its mode before its other fields were final",
                );
            }
            if value & 0x00003000 != old & 0x00003000 {
                kani::assert(value & 0x00003000 == 0x00002000, "PA6's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000040 == 0x00000000
                        && self.gpioa[2] & 0x00003000 == 0x00000000
                        && self.gpioa[3] & 0x00003000 == 0x00000000
                        && self.gpioa[8] & 0x0f000000 == 0x05000000,
                    "PA6 entered its mode before its other fields were final",
                );
            }
            if value & 0x0000c000 != old & 0x0000c000 {
                kani::assert(value & 0x0000c000 == 0x00008000, "PA7's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000080 == 0x00000000
                        && self.gpioa[2] & 0x0000c000 == 0x00004000
                        && self.gpioa[3] & 0x0000c000 == 0x00000000
                        && self.gpioa[8] & 0xf0000000 == 0x50000000,
                    "PA7 entered its mode before its other fields were final",
                );
            }
            kani::assert(
                value & !0x003cfc03 == old & !0x003cfc03,
                "a GpioA MODER write moved a pin the topology does not use",
            );
        }
        if block != Block::Pwr {
            let changed = if matches!((block, offset), (Block::GpioA, 0x18)) {
                value
            } else {
                *self.slot(block, offset) ^ value
            };
            kani::assert(
                changed & !self.footprint(block, offset) == 0,
                "a write changed a bit outside the running action's footprint",
            );
        }
        *self.slot(block, offset) = value;
    }
    // A byte access models the register as its word: the low byte read, the
    // byte written zero-extended, under every rule above.
    fn read8(&mut self, token: sealed::Token, block: Block, offset: usize) -> u8 {
        self.read(token, block, offset).to_le_bytes()[0]
    }
    fn write8(&mut self, token: sealed::Token, block: Block, offset: usize, value: u8) {
        self.write(token, block, offset, u32::from(value));
    }
}

/// The spi1 part's share of the state the specification allows, from
/// any starting image: its own fields as solved, and every bit no action
/// may change unchanged. Another part's bits are that part's to prove.
fn check_final_spi1(before: &ImageSpi1, after: &ImageSpi1) {
    // PWR is before plus exactly the declared supply and VOS Scale 2
    // (aethelgard_ir::vos::cr3_supply_bits, D3CR_VOS_SCALE2).
    kani::assert(
        after.pwr[3] == (before.pwr[3] & !0x00000007) | 0x00000002,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: CR3's supply bits are not the rule's, or another bit moved",
    );
    kani::assert(
        after.pwr[6] & 0x0000c000 == 0x00008000,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: D3CR.VOS is not 10",
    );
    kani::assert(
        after.pwr[6] & !0x00002000 == 0x00008000,
        "PWR is not before plus exactly the declared supply and VOS Scale 2: D3CR is not the rule's whole word",
    );
    kani::assert(after.pwr[0] == before.pwr[0], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 0 changed");
    kani::assert(after.pwr[1] == before.pwr[1], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 1 changed");
    kani::assert(after.pwr[2] == before.pwr[2], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 2 changed");
    kani::assert(after.pwr[4] == before.pwr[4], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 4 changed");
    kani::assert(after.pwr[5] == before.pwr[5], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 5 changed");
    kani::assert(after.pwr[7] == before.pwr[7], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 7 changed");
    kani::assert(after.pwr[8] == before.pwr[8], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 8 changed");
    kani::assert(after.pwr[9] == before.pwr[9], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 9 changed");
    kani::assert(after.pwr[10] == before.pwr[10], "PWR is not before plus exactly the declared supply and VOS Scale 2: word 10 changed");
    kani::assert(after.gpioa[1] == 0x00000000, "GpioA OTYPER is not the solved word");
    kani::assert(after.gpioa[3] == 0x64000000, "GpioA PUPDR is not the solved word");
    kani::assert(
        after.gpioa[0] & 0x0000fc03 == 0x0000a801,
        "GpioA word 0: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[0] & !0x0000fc03 == before.gpioa[0] & !0x0000fc03,
        "GpioA word 0: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[2] & 0x0000fc03 == 0x00004400,
        "GpioA word 2: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[2] & !0x0000fc03 == before.gpioa[2] & !0x0000fc03,
        "GpioA word 2: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[8] & 0xfff00000 == 0x55500000,
        "GpioA word 8: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[8] & !0xfff00000 == before.gpioa[8] & !0xfff00000,
        "GpioA word 8: an unsolved pin's field changed",
    );
    kani::assert(after.gpioa[5] & 0x00000001 != 0, "PA0, a chip select, is not high once its bus started");
    kani::assert(
        after.gpioa[5] & !0x00000001 == before.gpioa[5] & !0x00000001,
        "GpioA word 5: a level no solved output owns changed",
    );
    kani::assert(after.gpioa[4] == before.gpioa[4], "GpioA word 4 changed");
    kani::assert(after.gpioa[7] == before.gpioa[7], "GpioA word 7 changed");
    kani::assert(after.gpioa[9] == before.gpioa[9], "GpioA word 9 changed");
    let mut rcc = before.rcc;
    rcc[56] |= 0x00000001;
    rcc[60] |= 0x00001000;
    let mut rely = [0u32; 76];
    rely[56] = 0x00000002;
    rely[58] = 0x00200000;
    // Word by word: `==` on the arrays is a `memcmp` loop under CBMC.
    for i in 0..76 {
        kani::assert(
            after.rcc[i] & !rely[i] == rcc[i] & !rely[i],
            "RCC is not before plus exactly the solved clock gates and selections",
        );
    }
    kani::assert(
        after.spi1[0] == 0x00001000,
        "Spi1 CR1 is not the rule's word (aethelgard_ir::silicon::spi_words)",
    );
    kani::assert(
        after.spi1[2] == 0x10070007,
        "Spi1 CFG1 is not the rule's word (aethelgard_ir::silicon::spi_words)",
    );
    kani::assert(
        after.spi1[3] == 0x84400000,
        "Spi1 CFG2 is not the rule's word (aethelgard_ir::silicon::spi_words)",
    );
    kani::assert(after.spi1[1] == before.spi1[1], "Spi1 word 1 changed");
    kani::assert(after.spi1[4] == before.spi1[4], "Spi1 word 4 changed");
    kani::assert(after.spi1[5] == before.spi1[5], "Spi1 word 5 changed");
    kani::assert(after.spi1[6] == before.spi1[6], "Spi1 word 6 changed");
    kani::assert(after.spi1[7] == before.spi1[7], "Spi1 word 7 changed");
    kani::assert(after.spi1[8] == before.spi1[8], "Spi1 word 8 changed");
    kani::assert(after.spi1[9] == before.spi1[9], "Spi1 word 9 changed");
    kani::assert(after.spi1[10] == before.spi1[10], "Spi1 word 10 changed");
    kani::assert(after.spi1[11] == before.spi1[11], "Spi1 word 11 changed");
    kani::assert(after.spi1[12] == before.spi1[12], "Spi1 word 12 changed");
    kani::assert(after.spi1[13] == before.spi1[13], "Spi1 word 13 changed");
    kani::assert(after.spi1[14] == before.spi1[14], "Spi1 word 14 changed");
    kani::assert(after.spi1[15] == before.spi1[15], "Spi1 word 15 changed");
    kani::assert(after.spi1[16] == before.spi1[16], "Spi1 word 16 changed");
    kani::assert(after.spi1[17] == before.spi1[17], "Spi1 word 17 changed");
    kani::assert(after.spi1[18] == before.spi1[18], "Spi1 word 18 changed");
    kani::assert(after.spi1[19] == before.spi1[19], "Spi1 word 19 changed");
    kani::assert(after.spi1[20] == before.spi1[20], "Spi1 word 20 changed");
}

/// The spi1 part of the whole schedule (`AET-WO-3303` §1.2): every order
/// the typestate API admits of its 9 actions, under the rely that
/// any other part's action may have run between any two of them. Each
/// write may change only its running action's footprint; the parts'
/// footprints are disjoint, so together the parts prove every schedule
/// of the whole board.
/// No step touches a USART, its pins or its clock gate: the final check holds
/// them at their starting values, the image holds no USART block, and any
/// access to one fails. Each port's bring-up is
/// `usartN_start_writes_the_solved_values`' (`AET-WO-4300b`: USART steps in
/// this schedule ran out of CBMC's memory).
#[kani::proof]
#[kani::unwind(77)]
fn every_valid_sequence_spi1() {
    let mut img = ImageSpi1 {
        rcc: kani::any(),
        pwr: kani::any(),
        gpioa: kani::any(),
        spi1: kani::any(),
        running: u8::MAX,
    };
    let before = img;
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    // The bring-up's first step, as `main` takes it (`AET-WO-4240v` §1.4): it
    // touches only PWR (`pwr_scale2_is_once_in_order_and_bounded`), and no
    // action touches PWR, so it commutes with every action.
    let scale2 = board.pwr.scale2(&mut img, 1);
    kani::assume(scale2.is_ok());
    let scale2 = scale2.unwrap();
    let mut gpioa = Some(board.gpioa);
    let mut spi1 = Some(board.spi1);
    let mut spi1_clocked = None;
    let mut spi1_done = false;
    let mut pa0 = None;
    let mut pa0_done = None;
    let mut pa5 = None;
    let mut pa5_done = None;
    let mut pa6 = None;
    let mut pa6_done = None;
    let mut pa7 = None;
    let mut pa7_done = None;
    let mut clock = None;
    let mut kernels = None;
    for _ in 0..9 {
        img.rely();
        let action: u8 = kani::any();
        match action {
            0 => {
                kani::assume(gpioa.is_some());
                img.running = 0;
                let pins = rcc.enable_gpioa(&mut img, gpioa.take().unwrap(), scale2).split(&mut img);
                pa0 = Some(pins.pa0);
                pa5 = Some(pins.pa5);
                pa6 = Some(pins.pa6);
                pa7 = Some(pins.pa7);
            }
            1 => {
                kani::assume(spi1.is_some() && kernels.is_some());
                img.running = 1;
                spi1_clocked = Some(rcc.enable_spi1(&mut img, spi1.take().unwrap(), scale2, kernels.as_ref().unwrap()));
            }
            2 => {
                kani::assume(pa0.is_some());
                img.running = 2;
                let mut pin = pa0.take().unwrap().into_output(&mut img);
                if kani::any() {
                    if kani::any() {
                        pin.set_low(&mut img);
                        kani::assert(img.gpioa[6] == 0x00010000, "PA0 set_low did not reset it");
                        kani::cover!(true, "PA0 driven low");
                    } else {
                        pin.set_high(&mut img);
                        kani::assert(img.gpioa[6] == 0x00000001, "PA0 set_high did not set it");
                        kani::cover!(true, "PA0 driven high");
                    }
                }
                pa0_done = Some(pin);
            }
            3 => {
                kani::assume(pa5.is_some());
                img.running = 3;
                let pin = pa5.take().unwrap().into_spi1_sck(&mut img);
                pa5_done = Some(pin);
            }
            4 => {
                kani::assume(pa6.is_some());
                img.running = 4;
                let pin = pa6.take().unwrap().into_spi1_miso(&mut img);
                pa6_done = Some(pin);
            }
            5 => {
                kani::assume(pa7.is_some());
                img.running = 5;
                let pin = pa7.take().unwrap().into_spi1_mosi(&mut img);
                pa7_done = Some(pin);
            }
            6 => {
                kani::assume(spi1_clocked.is_some() && clock.is_some() && pa5_done.is_some() && pa7_done.is_some() && pa6_done.is_some() && pa0_done.is_some());
                img.running = 6;
                let i = spi1_clocked.take().unwrap();
                let _bus = i.init::<_>(&mut img, clock.as_ref().unwrap(), pa5_done.take().unwrap(), pa7_done.take().unwrap(), pa6_done.take().unwrap(), Spi1Selects { pa0: pa0_done.take().unwrap() });
                kani::cover!(true, "SPI1 started");
                spi1_done = true;
            }
            7 => {
                kani::assume(clock.is_none());
                img.running = 7;
                let read = rcc.reset_clock(&mut img, &scale2);
                kani::assume(read.is_ok());
                clock = read.ok();
                kani::cover!(true, "the reset clock was read");
            }
            8 => {
                kani::assume(clock.is_some() && kernels.is_none());
                img.running = 8;
                kernels = Some(spi_kernels_token(&mut rcc, clock.as_ref().unwrap()));
                kani::cover!(true, "the SPI kernel clocks were selected");
            }
            _ => kani::assume(false),
        }
    }
    kani::assert(spi1_done, "the schedule did not start SPI1");
    check_final_spi1(&before, &img);
    kani::cover!(true, "the end of a complete schedule is reachable");
}

/// I2c1's registers as a transfer may touch them, in order. `stage` is 0 before
/// the first START, 1 in the write phase, 2 in the read phase, 3 after the
/// flags are cleared.
struct I2c1Spy {
    stage: u8,
    isr_reads: u32,
    bytes_written: usize,
}

impl sealed::Sealed for I2c1Spy {}

impl Registers for I2c1Spy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::I2c1, "a I2c1 transfer read another block");
        if offset == 0x18 {
            kani::assert(self.stage >= 1, "ISR polled before the START");
            self.isr_reads += 1;
            kani::any()
        } else if offset == 0x24 {
            kani::assert(self.stage == 2, "RXDR read outside the read phase");
            kani::any()
        } else {
            kani::assert(false, "a I2c1 transfer read a register it does not own");
            0
        }
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        kani::assert(block == Block::I2c1, "a I2c1 transfer wrote another block");
        if offset == 0x04 {
            kani::assert(value & 0x00002000 != 0, "CR2 written without START");
            if value & 0x00000400 != 0 {
                kani::assert(self.stage <= 1, "the read phase did not follow the write phase");
                kani::assert(value & 0x02000000 != 0, "a read ends without AUTOEND");
                kani::assert(
                    self.stage == 0 || self.isr_reads as usize > self.bytes_written,
                    "the read phase began without waiting for TC",
                );
                self.stage = 2;
            } else {
                kani::assert(self.stage == 0, "the write phase is not first");
                self.stage = 1;
            }
        } else if offset == 0x28 {
            kani::assert(self.stage == 1, "TXDR written outside the write phase");
            self.bytes_written += 1;
        } else if offset == 0x1c {
            kani::assert(self.stage >= 1, "flags cleared before the START");
            kani::assert(value == 0x00000020 | 0x00000010, "ICR cleared more than STOPCF and NACKCF");
            self.stage = 3;
        } else {
            kani::assert(false, "a I2c1 transfer wrote a register it does not own");
        }
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "a I2c1 transfer made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "a I2c1 transfer made a byte access");
    }
}

/// A transfer of any address, up to two bytes each way and any answers, with
/// each wait bounded at two reads of `ISR`: touches only I2c1, in order, within
/// the bound, and ends in the result its phases imply.
#[kani::proof]
#[kani::unwind(6)]
fn i2c1_transfer_is_bounded_and_ordered() {
    let mut img = Image {
        rcc: kani::any(),
        pwr: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let scale2 = scale2_token(board.pwr);
    let clock = rcc.reset_clock(&mut img, &scale2);
    kani::assume(clock.is_ok());
    let clock = clock.unwrap();
    let gpiob = rcc.enable_gpiob(&mut img, board.gpiob, scale2).split(&mut img);
    let pb6 = gpiob.pb6.into_i2c1_scl(&mut img);
    let pb7 = gpiob.pb7.into_i2c1_sda(&mut img);
    let mut bus = rcc
        .enable_i2c1(&mut img, board.i2c1, scale2)
        .init::<i2c1_speed::Standard100k, _>(&mut img, &clock, pb6, pb7);
    let mut spy = I2c1Spy { stage: 0, isr_reads: 0, bytes_written: 0 };
    let (wl, rl): (usize, usize) = (kani::any(), kani::any());
    kani::assume(wl <= 2 && rl <= 2);
    let out: [u8; 2] = kani::any();
    let mut back = [0u8; 2];
    let spins = 2;
    let result = bus.transfer_within(&mut spy, kani::any(), &out[..wl], &mut back[..rl], spins);
    let waits = wl + usize::from(wl > 0 && rl > 0) + rl + usize::from(wl + rl > 0);
    kani::assert(
        spy.isr_reads as usize <= waits * spins as usize,
        "a wait read ISR more often than its bound",
    );
    kani::assert((wl + rl == 0) == (spy.stage == 0), "a transfer of nothing touched a register, or one of something did not");
    if wl + rl > 0 {
        kani::assert(spy.stage == 3, "a transfer did not end by clearing its flags");
    }
    match result {
        Ok(n) => {
            kani::assert(n == rl && spy.bytes_written == wl, "Ok without every byte moved");
            kani::cover!(wl > 0 && rl > 0, "I2c1 wrote, then read");
            kani::cover!(wl > 0 && rl == 0, "I2c1 wrote only");
            kani::cover!(wl == 0 && rl > 0, "I2c1 read only");
        }
        Err(I2cError::Txis) => kani::cover!(true, "I2c1 timed out waiting for TXIS"),
        Err(I2cError::Tc) => kani::cover!(true, "I2c1 timed out waiting for TC"),
        Err(I2cError::Rxne) => kani::cover!(true, "I2c1 timed out waiting for RXNE"),
        Err(I2cError::Stop) => kani::cover!(true, "I2c1 timed out waiting for STOPF"),
        Err(I2cError::Length) => kani::assert(false, "a transfer of at most two bytes was refused as too long"),
    }
}

/// Spi1's registers and its devices' chip selects as a transfer may touch them,
/// in order. `stage` is 0 before, 1 once TSIZE is set, 2 once the device is
/// selected, 3 once enabled, 4 once started, 5 once EOT is cleared, 6 once
/// disabled, 7 once deselected.
struct Spi1Spy {
    device: Spi1Device,
    out: [u8; 2],
    wl: usize,
    stage: u8,
    cr1: u32,
    tsize: u32,
    sr_reads: u32,
    rxp: bool,
    /// `SR.EOT` read set once every frame was received.
    eot: bool,
    /// Reads of `SR` after `EOT` was read set: the erratum's delay.
    after_eot: u32,
    /// `CFG2` as `init` left it in the harness image.
    cfg2: u32,
    sent: usize,
    received: usize,
    touched: bool,
}

impl Spi1Spy {
    /// The device's chip select: its port, and its BSRR reset and set words.
    fn select(&self) -> (Block, u32, u32) {
        match self.device {
            Spi1Device::U4 => (Block::GpioA, 0x00010000, 0x00000001),
        }
    }
}

impl sealed::Sealed for Spi1Spy {}

impl Registers for Spi1Spy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        self.touched = true;
        kani::assert(block == Block::Spi1, "a Spi1 transfer read another block");
        if offset == 0x00 {
            kani::assert(false, "a Spi1 transfer read CR1: it writes whole words (AET-WO-4230 D5)");
            self.cr1
        } else if offset == 0x14 {
            kani::assert(self.stage == 4, "SR polled outside the transfer");
            self.sr_reads += 1;
            if self.eot {
                self.after_eot += 1;
            }
            let v: u32 = kani::any();
            self.rxp = v & 0x00000001 != 0;
            if v & 0x00000008 != 0 && self.received as u32 == self.tsize {
                self.eot = true;
            }
            v
        } else {
            kani::assert(false, "a Spi1 transfer read a register it does not own");
            0
        }
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        self.touched = true;
        let (port, select, deselect) = self.select();
        if block == port && offset == 0x18 && value == select {
            kani::assert(self.stage == 1, "the device was selected out of order");
            self.stage = 2;
        } else if block == port && offset == 0x18 && value == deselect {
            kani::assert(self.stage == 6, "the device was deselected before the peripheral was disabled");
            self.stage = 7;
        } else if block == Block::Spi1 && offset == 0x04 {
            kani::assert(self.stage == 0, "CR2 written out of order");
            kani::assert(self.cr1 & 0x00000001 == 0, "TSIZE written while the peripheral is enabled");
            self.tsize = value;
            self.stage = 1;
        } else if block == Block::Spi1 && offset == 0x00 {
            // Each `CR1` write is the rule's whole word for its stage
            // (`aethelgard_ir::silicon::spi_words`), and none sets `SPE`
            // before master mode with software slave select (the 3302
            // bench: with `SSM` 0 the first `SPE` raised `MODF`).
            if value & 0x00000001 != 0 {
                kani::assert(self.cfg2 & 0x84400000 == 0x84400000, "SPE set before CFG2 holds MASTER and SSM");
                kani::assert(value & 0x00001000 != 0, "SPE set without SSI");
            }
            if self.stage == 2 {
                kani::assert(value == 0x00001001, "the peripheral was not enabled with SSI, alone");
                self.stage = 3;
            } else if self.stage == 3 {
                kani::assert(value == 0x00001201, "the transfer was not started with SSI and SPE, alone");
                self.stage = 4;
            } else if self.stage == 5 {
                kani::assert(value == 0x00001000, "the peripheral was not left idle: SSI, alone");
                self.stage = 6;
            } else {
                kani::assert(false, "CR1 written out of order");
            }
            self.cr1 = value;
        } else if block == Block::Spi1 && offset == 0x18 {
            kani::assert(self.stage == 4, "EOT cleared out of order");
            kani::assert(value == 0x00000008, "IFCR cleared more than EOTC");
            self.stage = 5;
        } else {
            kani::assert(false, "a Spi1 transfer wrote a register it does not own, or another device's chip select");
        }
    }
    fn read8(&mut self, _: sealed::Token, block: Block, offset: usize) -> u8 {
        self.touched = true;
        kani::assert(block == Block::Spi1 && offset == 0x30, "a byte read of anything but RXDR");
        kani::assert(self.stage == 4, "RXDR read outside the transfer");
        kani::assert(self.rxp, "RXDR read without RXP");
        self.rxp = false;
        self.received += 1;
        kani::any()
    }
    fn write8(&mut self, _: sealed::Token, block: Block, offset: usize, value: u8) {
        self.touched = true;
        kani::assert(block == Block::Spi1 && offset == 0x20, "a byte write to anything but TXDR");
        kani::assert(self.stage == 4, "TXDR written outside the transfer");
        let expected = if self.sent < self.wl { self.out[self.sent] } else { 0 };
        kani::assert(value == expected, "a frame is not the caller's byte, or a dummy is not 0x00");
        self.sent += 1;
        kani::assert(self.sent as u32 <= self.tsize, "more frames sent than TSIZE");
    }
}

/// A transfer of any device, up to two bytes out and three in (an identity
/// read is one and three) and any answers, with each wait bounded at two reads
/// of `SR`: selects that device before its first frame and deselects it after
/// the peripheral is disabled, also after a wait that expired; reads `RXDR`
/// only after `RXP`; writes `CR1` only whole and never reads it; and returns
/// `Ok` only when every frame moved, `EOT` was read set after the last, before
/// `EOTC`, and the erratum's delay followed it (ES0392 Rev 16 §2.22.6).
#[kani::proof]
#[kani::unwind(5)]
fn spi1_transfer_is_bounded_and_ordered() {
    let mut img = Image {
        rcc: kani::any(),
        pwr: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let scale2 = scale2_token(board.pwr);
    let clock = rcc.reset_clock(&mut img, &scale2);
    kani::assume(clock.is_ok());
    let clock = clock.unwrap();
    let gpioa = rcc.enable_gpioa(&mut img, board.gpioa, scale2).split(&mut img);
    let pa5 = gpioa.pa5.into_spi1_sck(&mut img);
    let pa7 = gpioa.pa7.into_spi1_mosi(&mut img);
    let pa6 = gpioa.pa6.into_spi1_miso(&mut img);
    let pa0 = gpioa.pa0.into_output(&mut img);
    let kernels = spi_kernels_token(&mut rcc, &clock);
    let mut bus = rcc
        .enable_spi1(&mut img, board.spi1, scale2, &kernels)
        .init(&mut img, &clock, pa5, pa7, pa6, Spi1Selects { pa0 });
    let devices = [Spi1Device::U4];
    let pick: usize = kani::any();
    kani::assume(pick < devices.len());
    let device = devices[pick];
    // The state `init` and every transfer leave: `CR1` idle, `SSI` alone
    // (the schedule harness or each of its parts, and the end of this proof);
    // `CFG2` as `init` wrote it.
    let cr1: u32 = 0x00001000;
    let cfg2 = img.spi1[3];
    let (wl, rl): (usize, usize) = (kani::any(), kani::any());
    kani::assume(wl <= 2 && rl <= 3);
    let out: [u8; 2] = kani::any();
    let mut back = [0u8; 3];
    let mut spy = Spi1Spy { device, out, wl, stage: 0, cr1, tsize: 0, sr_reads: 0, rxp: false, eot: false, after_eot: 0, cfg2, sent: 0, received: 0, touched: false };
    let spins = 2;
    let result = bus.transfer_within(&mut spy, device, &out[..wl], &mut back[..rl], spins);
    let frames = wl + rl;
    if frames == 0 {
        kani::assert(result == Err(SpiError::Length), "a transfer of nothing was not refused");
        kani::assert(!spy.touched, "a refused transfer touched a register");
        kani::cover!(true, "Spi1 refused a transfer of nothing");
        return;
    }
    kani::assert(spy.stage == 7, "a transfer did not end disabled and deselected");
    kani::assert(spy.tsize == frames as u32, "TSIZE is not the frames of the transfer");
    kani::assert(
        spy.sr_reads as usize <= (frames + 1) * spins as usize + 16,
        "a wait read SR more often than its bound",
    );
    kani::assert(spy.cr1 == 0x00001000, "a transfer did not leave CR1 idle");
    match result {
        Ok(n) => {
            kani::assert(n == rl && spy.sent == frames && spy.received == frames, "Ok without every frame moved");
            kani::assert(spy.eot, "Ok without EOT read after the last frame, before EOTC");
            kani::assert(spy.after_eot >= 5, "SPE cleared sooner than one SCK period after EOT (ES0392 Rev 16 2.22.6)");
            kani::cover!(wl > 0 && rl > 0, "Spi1 wrote, then read");
            kani::cover!(wl == 1 && rl == 3, "Spi1 made an identity read's frames");
        }
        Err(SpiError::Rxp) => {
            kani::assert(spy.received < frames, "Rxp after every frame moved");
            kani::cover!(true, "Spi1 timed out waiting for RXP");
        }
        Err(SpiError::Eot) => {
            kani::assert(spy.received == frames && !spy.eot, "Eot with a frame missing, or after EOT was read");
            kani::cover!(true, "Spi1 timed out waiting for EOT");
        }
        Err(SpiError::Length) => kani::assert(false, "a transfer of at most five frames was refused"),
    }
}

/// More frames than [`SPI_MAX_FRAMES`] are refused, and touch no register. The
/// bound fails the proof if a loop of the transfer is reached.
#[kani::proof]
#[kani::unwind(2)]
fn spi1_transfer_refuses_too_many_frames() {
    let mut img = Image {
        rcc: kani::any(),
        pwr: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let scale2 = scale2_token(board.pwr);
    let clock = rcc.reset_clock(&mut img, &scale2);
    kani::assume(clock.is_ok());
    let clock = clock.unwrap();
    let gpioa = rcc.enable_gpioa(&mut img, board.gpioa, scale2).split(&mut img);
    let pa5 = gpioa.pa5.into_spi1_sck(&mut img);
    let pa7 = gpioa.pa7.into_spi1_mosi(&mut img);
    let pa6 = gpioa.pa6.into_spi1_miso(&mut img);
    let pa0 = gpioa.pa0.into_output(&mut img);
    let kernels = spi_kernels_token(&mut rcc, &clock);
    let mut bus = rcc
        .enable_spi1(&mut img, board.spi1, scale2, &kernels)
        .init(&mut img, &clock, pa5, pa7, pa6, Spi1Selects { pa0 });
    let devices = [Spi1Device::U4];
    let pick: usize = kani::any();
    kani::assume(pick < devices.len());
    let device = devices[pick];
    // The state `init` and every transfer leave: `CR1` idle, `SSI` alone
    // (the schedule harness or each of its parts, and the end of this proof);
    // `CFG2` as `init` wrote it.
    let cr1: u32 = 0x00001000;
    let cfg2 = img.spi1[3];
    let (wl, out) = (1, [0u8; 2]);
    let mut back = [0u8; SPI_MAX_FRAMES as usize];
    let mut spy = Spi1Spy { device, out, wl, stage: 0, cr1, tsize: 0, sr_reads: 0, rxp: false, eot: false, after_eot: 0, cfg2, sent: 0, received: 0, touched: false };
    let result = bus.transfer(&mut spy, device, &out[..wl], &mut back);
    kani::assert(result == Err(SpiError::Length), "a transfer of too many frames was not refused");
    kani::assert(!spy.touched, "a refused transfer touched a register");
    kani::cover!(true, "Spi1 refused too many frames");
}

/// The registers `reset_clock` reads, as any words.
struct ClockSpy {
    cr: u32,
    cfgr: u32,
    d1cfgr: u32,
    d2cfgr: u32,
    d1ccipr: u32,
    d2ccip1r: u32,
    d2ccip2r: u32,
    reads: [bool; 7],
}

impl sealed::Sealed for ClockSpy {}

impl Registers for ClockSpy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::Rcc, "reset_clock read outside RCC");
        if offset == 0x000 {
            kani::assert(!self.reads[0], "reset_clock read CR twice");
            self.reads[0] = true;
            self.cr
        } else if offset == 0x010 {
            kani::assert(!self.reads[1], "reset_clock read CFGR twice");
            self.reads[1] = true;
            self.cfgr
        } else if offset == 0x018 {
            kani::assert(!self.reads[2], "reset_clock read D1CFGR twice");
            self.reads[2] = true;
            self.d1cfgr
        } else if offset == 0x01c {
            kani::assert(!self.reads[3], "reset_clock read D2CFGR twice");
            self.reads[3] = true;
            self.d2cfgr
        } else if offset == 0x04c {
            kani::assert(!self.reads[4], "reset_clock read D1CCIPR twice");
            self.reads[4] = true;
            self.d1ccipr
        } else if offset == 0x050 {
            kani::assert(!self.reads[5], "reset_clock read D2CCIP1R twice");
            self.reads[5] = true;
            self.d2ccip1r
        } else if offset == 0x054 {
            kani::assert(!self.reads[6], "reset_clock read D2CCIP2R twice");
            self.reads[6] = true;
            self.d2ccip2r
        } else {
            kani::assert(false, "reset_clock read a register it does not check");
            0
        }
    }
    fn write(&mut self, _: sealed::Token, _: Block, _: usize, _: u32) {
        kani::assert(false, "reset_clock wrote a register");
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "reset_clock made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "reset_clock made a byte access");
    }
}

/// `reset_clock` is `Ok` exactly when every field it checks is 0, its reset
/// value, for any words in its registers; it reads each register once and
/// writes none.
#[kani::proof]
fn reset_clock_is_ok_exactly_at_reset() {
    let (cr, cfgr, d1cfgr, d2cfgr, d1ccipr, d2ccip1r, d2ccip2r) = (kani::any(), kani::any(), kani::any(), kani::any(), kani::any(), kani::any(), kani::any());
    let mut spy = ClockSpy { cr, cfgr, d1cfgr, d2cfgr, d1ccipr, d2ccip1r, d2ccip2r, reads: [false; 7] };
    let board = Board::take().unwrap();
    let scale2 = scale2_token(board.pwr);
    let result = board.rcc.reset_clock(&mut spy, &scale2);
    let reset = (cr >> 3) & 0x3 == 0
        && (cfgr >> 3) & 0x7 == 0
        && (cfgr >> 15) & 0x1 == 0
        && (d1cfgr >> 8) & 0xf == 0
        && (d1cfgr >> 4) & 0x7 == 0
        && d1cfgr & 0xf == 0
        && (d2cfgr >> 4) & 0x7 == 0
        && (d2cfgr >> 8) & 0x7 == 0
        && (d1ccipr >> 28) & 0x3 == 0
        && (d2ccip1r >> 12) & 0x7 == 0
        && (d2ccip1r >> 16) & 0x7 == 0
        && (d2ccip2r >> 3) & 0x7 == 0
        && d2ccip2r & 0x7 == 0
        && (d2ccip2r >> 12) & 0x3 == 0;
    kani::assert(result.is_ok() == reset, "reset_clock is not Ok exactly at the reset clock");
    kani::assert(spy.reads[0] && spy.reads[1] && spy.reads[2] && spy.reads[3] && spy.reads[4] && spy.reads[5] && spy.reads[6], "reset_clock did not read every register it checks");
    kani::cover!(result.is_ok(), "the reset clock is admitted");
    kani::cover!(result.is_err(), "another clock is refused");
}

/// USART1's bring-up as the hardware sees it: RCC and its pins' ports go to
/// the harness image, under its gate and write rules; each USART1 write is
/// recorded, after its gate is set; any other access fails.
struct Usart1Bringup {
    img: Image,
    writes: [(usize, u32); 4],
    n: usize,
}

impl sealed::Sealed for Usart1Bringup {}

impl Registers for Usart1Bringup {
    fn read(&mut self, token: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::Rcc || block == Block::GpioA, "USART1's bring-up read a block other than RCC and its pins' ports");
        self.img.read(token, block, offset)
    }
    fn write(&mut self, token: sealed::Token, block: Block, offset: usize, value: u32) {
        if block == Block::Usart1 {
            kani::assert(self.img.rcc[60] & 0x00000010 != 0, "USART1 written before RCC_APB2ENR bit 4 is set");
            kani::assert(self.n < 4, "USART1's bring-up wrote it more than 4 times");
            if self.n < 4 {
                self.writes[self.n] = (offset, value);
            }
            self.n += 1;
        } else {
            kani::assert(block == Block::Rcc || block == Block::GpioA, "USART1's bring-up wrote a block other than RCC, its pins' ports and USART1");
            self.img.write(token, block, offset, value);
        }
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "USART1's bring-up made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "USART1's bring-up made a byte access");
    }
}

/// Serial port `CONSOLE`, brought up from the board as `Board::take` hands it
/// over, on any register contents: its pins' ports clocked, both pins in
/// their roles, the reset clock read, USART1 clocked and configured. RCC is
/// then before plus exactly those gates; the pins' fields hold their solved
/// values and no other field of their ports changed; and USART1 was written
/// exactly the solved `BRR`, `CR2`, `CR1`, then `CR1` with `UE`, in order, each
/// after its gate was set, and never read.
#[kani::proof]
fn usart1_start_writes_the_solved_values() {
    let img = Image {
        rcc: kani::any(),
        pwr: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let before = img;
    let mut spy = Usart1Bringup { img, writes: [(0, 0); 4], n: 0 };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let scale2 = scale2_token(board.pwr);
    let gpioa = rcc.enable_gpioa(&mut spy, board.gpioa, scale2).split(&mut spy);
    let pa9 = gpioa.pa9.into_usart1_tx(&mut spy);
    let pa10 = gpioa.pa10.into_usart1_rx(&mut spy);
    let clock = rcc.reset_clock(&mut spy, &scale2);
    kani::assume(clock.is_ok());
    let clock = clock.unwrap();
    let usart = rcc.enable_usart1(&mut spy, board.usart1, scale2);
    let _port = usart.configure(&mut spy, &clock, pa9, pa10);
    kani::assert(spy.n == 4, "USART1's bring-up did not write it exactly 4 times");
    kani::assert(spy.writes[0] == (0x0c, 0x0000022c), "USART1 write 1 is not BRR = 0x0000022c");
    kani::assert(spy.writes[1] == (0x04, 0x00000000), "USART1 write 2 is not CR2 = 0x00000000");
    kani::assert(spy.writes[2] == (0x00, 0x2000000c), "USART1 write 3 is not CR1 = 0x2000000c");
    kani::assert(spy.writes[3] == (0x00, 0x2000000d), "USART1 write 4 is not CR1 | UE = 0x2000000d");
    let mut rcc_after = before.rcc;
    rcc_after[56] |= 0x00000001;
    rcc_after[60] |= 0x00000010;
    for i in 0..76 {
        kani::assert(spy.img.rcc[i] == rcc_after[i], "RCC is not before plus exactly USART1's gate and its pins' ports'");
    }
    kani::assert(spy.img.gpioa[0] & 0x003c0000 == 0x00280000, "Usart1: a pin's field in gpioa word 0 is not its solved value");
    kani::assert(spy.img.gpioa[0] & !0x003c0000 == before.gpioa[0] & !0x003c0000, "Usart1's bring-up changed another pin's field in gpioa word 0");
    kani::assert(spy.img.gpioa[1] == 0x00000000, "Usart1: gpioa OTYPER is not the solved word");
    kani::assert(spy.img.gpioa[2] & 0x003c0000 == 0x00000000, "Usart1: a pin's field in gpioa word 2 is not its solved value");
    kani::assert(spy.img.gpioa[2] & !0x003c0000 == before.gpioa[2] & !0x003c0000, "Usart1's bring-up changed another pin's field in gpioa word 2");
    kani::assert(spy.img.gpioa[3] == 0x64000000, "Usart1: gpioa PUPDR is not the solved word");
    kani::assert(spy.img.gpioa[4] == before.gpioa[4], "Usart1's bring-up changed gpioa word 4");
    kani::assert(spy.img.gpioa[5] == before.gpioa[5], "Usart1's bring-up changed gpioa word 5");
    kani::assert(spy.img.gpioa[6] == before.gpioa[6], "Usart1's bring-up changed gpioa word 6");
    kani::assert(spy.img.gpioa[7] == before.gpioa[7], "Usart1's bring-up changed gpioa word 7");
    kani::assert(spy.img.gpioa[8] == before.gpioa[8], "Usart1's bring-up changed gpioa word 8");
    kani::assert(spy.img.gpioa[9] & 0x00000ff0 == 0x00000770, "Usart1: a pin's field in gpioa word 9 is not its solved value");
    kani::assert(spy.img.gpioa[9] & !0x00000ff0 == before.gpioa[9] & !0x00000ff0, "Usart1's bring-up changed another pin's field in gpioa word 9");
    kani::cover!(true, "USART1 brought up");
}

/// The flash controller as `Flash::option_status` may touch it.
struct FlashSpy {
    reads: u32,
    word: u32,
}

impl sealed::Sealed for FlashSpy {}

impl Registers for FlashSpy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::Flash && offset == 0x01c, "option_status read anything but FLASH_OPTSR_CUR");
        self.reads += 1;
        self.word
    }
    fn write(&mut self, _: sealed::Token, _: Block, _: usize, _: u32) {
        kani::assert(false, "option_status wrote a register: the firmware never programs the option bytes");
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "option_status made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "option_status made a byte access");
    }
}

/// The brown-out word is exactly one read of `FLASH_OPTSR_CUR`, returned as
/// read, for any word there; nothing is written.
#[kani::proof]
fn flash_option_status_is_one_read() {
    let word: u32 = kani::any();
    let mut spy = FlashSpy { reads: 0, word };
    let board = Board::take().unwrap();
    let read = board.flash.option_status(&mut spy);
    kani::assert(spy.reads == 1, "option_status did not read FLASH_OPTSR_CUR exactly once");
    kani::assert(read == word, "option_status did not return the word as read");
    kani::cover!(read & 0xc == 0xc, "BOR_LEV 11 is read");
}

/// PWR as `Pwr::scale2` may touch it: every read any word, the order held at
/// each access. `step`: 0 before the `CR3` read, 1 after it, 2 after the `CR3`
/// write, 3 after the read-back, 4 after the `D3CR` write.
struct PwrSpy {
    step: u8,
    cr3: u32,
    readback: u32,
    csr1_reads: u32,
    actvosrdy: bool,
    d3cr_reads: u32,
    vosrdy: bool,
    writes: u32,
}

impl sealed::Sealed for PwrSpy {}

impl Registers for PwrSpy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::Pwr, "scale2 touched a block other than PWR");
        let v: u32 = kani::any();
        if offset == 0x00c {
            kani::assert(self.step == 0 || self.step == 2, "CR3 read other than once before its write and once after");
            if self.step == 0 {
                self.cr3 = v;
                self.step = 1;
            } else {
                self.readback = v;
                self.step = 3;
            }
        } else if offset == 0x004 {
            kani::assert(
                self.step == 3 && self.readback & 0x00000003 == 0x00000002,
                "CSR1 polled before CR3 read back as declared (aethelgard_ir::vos::cr3_supply_bits)",
            );
            kani::assert(!self.actvosrdy, "CSR1 polled after ACTVOSRDY read 1");
            self.csr1_reads += 1;
            self.actvosrdy = v & 0x00002000 != 0;
        } else if offset == 0x018 {
            kani::assert(self.step == 4, "D3CR read before its write");
            kani::assert(!self.vosrdy, "D3CR polled after VOSRDY read 1");
            self.d3cr_reads += 1;
            self.vosrdy = v & 0x00002000 != 0;
        } else {
            kani::assert(false, "scale2 read a PWR register other than CSR1, CR3 and D3CR");
        }
        v
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        kani::assert(block == Block::Pwr, "scale2 touched a block other than PWR");
        self.writes += 1;
        if offset == 0x00c {
            kani::assert(self.step == 1, "CR3 written other than once, after its read");
            kani::assert(
                value == (self.cr3 & !0x00000007) | 0x00000002,
                "CR3 is not the word as read with the rule's supply bits (aethelgard_ir::vos::cr3_supply_bits)",
            );
            self.step = 2;
        } else if offset == 0x018 {
            kani::assert(
                self.step == 3 && self.readback & 0x00000003 == 0x00000002 && self.actvosrdy,
                "D3CR written other than once, after CR3 read back as declared and ACTVOSRDY read 1",
            );
            kani::assert(value == 0x00008000, "D3CR is not the rule's word (aethelgard_ir::vos::D3CR_VOS_SCALE2)");
            self.step = 4;
        } else {
            kani::assert(false, "scale2 wrote a PWR register other than CR3 and D3CR");
        }
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "scale2 made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "scale2 made a byte access");
    }
}

/// `Pwr::scale2` at a bound of two polls, on any words: `CR3` then `D3CR`
/// written, once each, in order, with the rule's words; nothing after a fault;
/// each outcome by its own name, `Scale2` only when `CR3` read back as declared
/// and `ACTVOSRDY` and `VOSRDY` each read 1 within the bound.
#[kani::proof]
#[kani::unwind(3)]
fn pwr_scale2_is_once_in_order_and_bounded() {
    let mut spy = PwrSpy {
        step: 0,
        cr3: 0,
        readback: 0,
        csr1_reads: 0,
        actvosrdy: false,
        d3cr_reads: 0,
        vosrdy: false,
        writes: 0,
    };
    let board = Board::take().unwrap();
    let result = board.pwr.scale2(&mut spy, 2);
    let declared = spy.step >= 3 && spy.readback & 0x00000003 == 0x00000002;
    kani::assert(spy.csr1_reads <= 2 && spy.d3cr_reads <= 2, "a wait read past its bound");
    match result {
        Ok(_) => {
            kani::assert(
                spy.step == 4 && spy.writes == 2 && declared && spy.actvosrdy && spy.vosrdy,
                "Scale2 without CR3 read back as declared and both bits read 1 after both writes",
            );
            kani::cover!(true, "Scale 2 reached");
        }
        Err(PwrFault::SupplyNotDeclared) => {
            kani::assert(
                spy.step == 3 && spy.writes == 1 && !declared,
                "SupplyNotDeclared other than on a CR3 read back undeclared, right after its one write",
            );
            kani::cover!(true, "the supply is not the declared one");
        }
        Err(PwrFault::ActvosrdyTimeout) => {
            kani::assert(
                spy.step == 3 && spy.writes == 1 && declared && !spy.actvosrdy && spy.csr1_reads == 2,
                "ActvosrdyTimeout other than after the bound's reads of CSR1, each 0",
            );
            kani::cover!(true, "ACTVOSRDY times out");
        }
        Err(PwrFault::VosrdyTimeout) => {
            kani::assert(
                spy.step == 4 && spy.writes == 2 && spy.actvosrdy && !spy.vosrdy && spy.d3cr_reads == 2,
                "VosrdyTimeout other than after the bound's reads of D3CR, each 0",
            );
            kani::cover!(true, "VOSRDY times out");
        }
    }
}

/// PWR always ready: `CR3` reads as last written, every other read all ones.
struct PwrReady {
    cr3: u32,
}

impl sealed::Sealed for PwrReady {}

impl Registers for PwrReady {
    fn read(&mut self, _: sealed::Token, _: Block, offset: usize) -> u32 {
        if offset == 0x00c { self.cr3 } else { !0 }
    }
    fn write(&mut self, _: sealed::Token, _: Block, offset: usize, value: u32) {
        if offset == 0x00c {
            self.cr3 = value;
        }
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {}
}

/// The token the targeted harnesses read the reset clock with: `scale2` on
/// [`PwrReady`], which returns `Ok` (`pwr_scale2_is_once_in_order_and_bounded`
/// proves the sequence itself).
fn scale2_token(pwr: Pwr) -> Scale2 {
    let token = pwr.scale2(&mut PwrReady { cr3: 0 }, 1);
    kani::assert(token.is_ok(), "scale2 refused a ready PWR");
    token.unwrap()
}

/// RCC as `select_spi_kernels` may touch it with the switch's PLL1 (AET-WO-4240e):
/// each write held to the contract's, in order; each `PLL1RDY` read any word.
struct SwitchSpy {
    writes: usize,
    pll_reads: u32,
    pll: bool,
    settle_reads: u32,
}

impl sealed::Sealed for SwitchSpy {}

impl Registers for SwitchSpy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        let v: u32 = kani::any();
        if block == Block::Rcc && offset == 0x000 && self.writes == 4 {
            kani::assert(!self.pll, "CR polled after PLL1RDY read 1");
            self.pll_reads += 1;
            self.pll = v & 0x02000000 != 0;
        } else if block == Block::Rcc && offset == 0x050 && self.writes == 5 {
            self.settle_reads += 1;
        } else {
            kani::assert(false, "the switch read a register out of the contract's order");
        }
        v
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        match self.writes {
            0 => kani::assert(block == Block::Rcc && offset == 0x028 && value == 0x00000050, "write 1 is not the contract's"),
            1 => kani::assert(block == Block::Rcc && offset == 0x02c && value == 0x0002000c, "write 2 is not the contract's"),
            2 => kani::assert(block == Block::Rcc && offset == 0x030 && value == 0x0101020f, "write 3 is not the contract's"),
            3 => kani::assert(block == Block::Rcc && offset == 0x000 && value == 0x01000001, "write 4 is not the contract's"),
            4 => kani::assert(block == Block::Rcc && offset == 0x050 && value == 0x00004000, "write 5 is not the contract's"),
            5 => kani::assert(block == Block::Rcc && offset == 0x000 && value == 0x00000001, "write 6 is not the contract's"),
            _ => kani::assert(false, "the switch wrote more than the contract's 6 words"),
        }
        kani::assert(self.writes < 4 || self.pll, "a select before PLL1RDY read 1");
        kani::assert(self.writes < 5 || self.settle_reads >= 8, "PLL1ON cleared before the transition's reads");
        self.writes += 1;
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "the switch made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "the switch made a byte access");
    }
}

/// `select_spi_kernels` with the switch's PLL1, on any `PLL1RDY` reads, its bound
/// symbolic, one or two reads: the contract's 6 words, in order, once each;
/// `SpiKernels` only once `PLL1RDY` read 1 and every word was written; a lock that does
/// not come [`KernelClockFault::Pll1NotLocked`] after exactly its bound's reads, each 0,
/// with nothing written after it.
#[kani::proof]
#[kani::unwind(3)]
fn spi_kernel_switch_is_in_order_bounded_and_named() {
    let pb: u32 = kani::any();
    kani::assume((1..=2).contains(&pb));
    let mut regs = SwitchReady { rcc: [0; 76] };
    let mut board = Board::take().unwrap();
    let scale2 = scale2_token(board.pwr);
    let reset = board.rcc.reset_clock(&mut regs, &scale2);
    kani::assert(reset.is_ok(), "the reset clock refused a reset RCC");
    let mut spy = SwitchSpy { writes: 0, pll_reads: 0, pll: false, settle_reads: 0 };
    match board.rcc.select_spi_kernels(&mut spy, &reset.unwrap(), pb) {
        Ok(_) => {
            kani::assert(spy.writes == 6 && spy.pll && spy.settle_reads == 8, "SpiKernels without every word written, PLL1RDY ready and the transition's reads");
            kani::cover!(true, "the kernel clocks are switched");
        }
        Err(KernelClockFault::Pll1NotLocked) => {
            kani::assert(spy.writes == 4 && !spy.pll && spy.pll_reads == pb, "Pll1NotLocked other than after the bound's reads of PLL1RDY, each 0, with nothing written after");
            kani::cover!(true, "PLL1RDY times out");
        }
    }
}

/// RCC always ready for the switch: each word reads as last written (0 at first, the
/// reset clock), `PLL1RDY` its ON bit.
struct SwitchReady {
    rcc: [u32; 76],
}

impl sealed::Sealed for SwitchReady {}

impl Registers for SwitchReady {
    fn read(&mut self, _: sealed::Token, _: Block, offset: usize) -> u32 {
        self.rcc[offset / 4]
    }
    fn write(&mut self, _: sealed::Token, _: Block, offset: usize, value: u32) {
        self.rcc[offset / 4] = if offset == 0x000 { value | ((value & 0x01000000) << 1) } else { value };
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {}
}

/// The token the other harnesses take: the selection on [`SwitchReady`], which returns
/// `Ok` (`spi_kernel_switch_is_in_order_bounded_and_named` proves the switch itself).
#[allow(dead_code)]
fn spi_kernels_token(rcc: &mut Rcc, clock: &ResetClock) -> SpiKernels {
    let mut regs = SwitchReady { rcc: [0; 76] };
    let kernels = rcc.select_spi_kernels(&mut regs, clock, 1);
    kani::assert(kernels.is_ok(), "the switch refused a ready RCC");
    kernels.unwrap()
}
